import os
import sys

import pytest

import click
from click.testing import CliRunner


def test_result_repr_success():
    @click.command()
    def cli():
        click.echo("ok")

    result = CliRunner().invoke(cli)
    assert repr(result) == "<Result okay>"


def test_result_repr_with_exception():
    @click.command()
    def cli():
        raise ValueError("boom")

    result = CliRunner().invoke(cli)
    assert repr(result) == f"<Result {result.exception!r}>"
    assert "ValueError" in repr(result)
    assert "boom" in repr(result)


def test_invoke_restores_original_stdout_stderr():
    @click.command()
    def cli():
        click.echo("hi")

    old_stdout = sys.stdout
    old_stderr = sys.stderr

    result = CliRunner().invoke(cli)

    assert result.exit_code == 0
    assert sys.stdout is old_stdout
    assert sys.stderr is old_stderr


def test_isolation_unsets_env_var_and_restores_it():
    @click.command()
    def cli():
        click.echo(str("TEST_CLICK_UNSET_ENV" in os.environ))

    os.environ["TEST_CLICK_UNSET_ENV"] = "present"
    try:
        runner = CliRunner()
        result = runner.invoke(cli, env={"TEST_CLICK_UNSET_ENV": None})
        assert result.output == "False\n"
        assert os.environ["TEST_CLICK_UNSET_ENV"] == "present"
    finally:
        del os.environ["TEST_CLICK_UNSET_ENV"]


@pytest.mark.skipif(
    sys.platform == "win32", reason="fd capture not supported on Windows"
)
def test_capture_fd_fileno_points_to_distinct_valid_fd():
    """In ``fd`` mode, ``sys.stdout.fileno()`` returns the saved original
    fd (not fd 1, which is redirected to the capture tmpfile), and that fd
    is a valid, open descriptor.
    """
    seen = {}

    @click.command()
    def cli():
        fd = sys.stdout.fileno()
        seen["fd"] = fd
        seen["fd_is_distinct_from_target"] = fd != 1
        os.fstat(fd)  # raises OSError if not a valid open fd

    runner = CliRunner(capture="fd")
    result = runner.invoke(cli)
    assert result.exit_code == 0, result.output
    assert seen["fd_is_distinct_from_target"]


def test_catch_exceptions_false_still_restores_streams_on_raise():
    @click.command()
    def cli():
        raise ValueError("boom")

    old_stdout = sys.stdout
    old_stderr = sys.stderr

    runner = CliRunner()
    with pytest.raises(ValueError):
        runner.invoke(cli, catch_exceptions=False)

    assert sys.stdout is old_stdout
    assert sys.stderr is old_stderr
